import{_ as t,o,c as a,an as d}from"./chunks/framework.ByZXu0sn.js";const f=JSON.parse('{"title":"Extension API","description":"","frontmatter":{},"headers":[],"relativePath":"developer/extending-api.md","filePath":"developer/extending-api.md","lastUpdated":null}'),r={name:"developer/extending-api.md"};function s(l,e,i,c,n,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="overview-extending" tabindex="-1">Extension API <a class="header-anchor" href="#overview-extending" aria-label="Permalink to &quot;Extension API {#overview-extending}&quot;">​</a></h1><p>Every name for a new type, with the arguments of each role; the <a href="/previews/PR883/developer/extending#extending">easy path</a> shows them in use.</p><h2 id="extending-roles" tabindex="-1">Roles <a class="header-anchor" href="#extending-roles" aria-label="Permalink to &quot;Roles {#extending-roles}&quot;">​</a></h2><p>A role is one job a new type can do, named by a type with no fields. A new type does its work in a <a href="/previews/PR883/lib/public#ComposableRecurrences.forward!"><code>forward!</code></a> method for each role it has, and may add a <a href="/previews/PR883/lib/public#ComposableRecurrences.pullback!"><code>pullback!</code></a> for each. The role is the second argument of <code>forward!</code> and the third of <code>pullback!</code>, and selects the method by dispatch.</p><ul><li><p><a href="/previews/PR883/lib/public#ComposableRecurrences.Step"><code>Step()</code></a> computes one step.</p></li><li><p><a href="/previews/PR883/lib/public#ComposableRecurrences.Init"><code>Init()</code></a> computes the starting state.</p></li><li><p><a href="/previews/PR883/lib/public#ComposableRecurrences.Pressure"><code>Pressure()</code></a> is a coupling&#39;s mixing.</p></li><li><p><a href="/previews/PR883/lib/public#ComposableRecurrences.Trace"><code>Trace()</code></a> is a modifier&#39;s record for a call with <code>record = (:trace,)</code>.</p></li></ul><p>Both methods write their outputs in place and return <code>nothing</code>, and a method that returns anything else is an error. <code>pullback!</code> receives the named tuple <code>grads</code>. Its field <code>grads.piece</code> is the mirror, the cotangents of the type&#39;s own fields, laid out as <a href="/previews/PR883/developer/extending-parameters#extending-mirror">The gradient mirror</a> gives. Its other fields hold the cotangents of the role&#39;s arguments.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Type</th><th style="text-align:right;"><code>forward!</code></th><th style="text-align:right;"><code>pullback!</code></th><th style="text-align:right;"><code>grads</code></th></tr></thead><tbody><tr><td style="text-align:right;">modifier step</td><td style="text-align:right;"><code>forward!(m, Step(), v, s, t)</code> updates <code>v</code> and <code>s</code></td><td style="text-align:right;"><code>pullback!(grads, m, Step(), v, s, t)</code></td><td style="text-align:right;">the mirror; <code>v</code> and <code>s</code> hold the cotangents of <code>v′</code> and <code>s′</code>; overwrite them with those of <code>v</code> and <code>s</code></td></tr><tr><td style="text-align:right;">initial state</td><td style="text-align:right;"><code>forward!(m, Init(), s, history)</code> writes <code>s</code></td><td style="text-align:right;"><code>pullback!(grads, m, Init(), s, history)</code></td><td style="text-align:right;">the mirror; <code>s</code> holds the cotangent of <code>s</code>; add into <code>history</code>, which may be <code>nothing</code></td></tr><tr><td style="text-align:right;">coupling</td><td style="text-align:right;"><code>forward!(C, Pressure(), q, p, t)</code> writes <code>q</code></td><td style="text-align:right;"><code>pullback!(grads, C, Pressure(), q, p, t)</code>, with <code>q === nothing</code></td><td style="text-align:right;">the mirror; <code>q</code> holds the cotangent of <code>q</code>; add into <code>p</code></td></tr></tbody></table><p>The rows for a <a href="/previews/PR883/developer/extending-steps#extending-blockwise">blockwise step</a>, a <a href="/previews/PR883/developer/extending-traces#extending-trace-own">trace</a> and a <a href="/previews/PR883/developer/extending-forms#extending-form-pullback">form</a> are on their pages; the arguments mean the same in every role:</p><ul><li><p><code>t</code> is the absolute time, counted from 1 as <code>start</code> and <code>stop</code> are.</p></li><li><p><code>v</code> holds one value per <a href="/previews/PR883/explanation/operators#explanation-step">stratum</a>, indexed by stratum, and <code>s</code> is the modifier&#39;s state after the previous step, with <a href="/previews/PR883/lib/public#ComposableRecurrences.nstate"><code>nstate</code></a> entries.</p></li><li><p><code>history</code> is the call&#39;s <code>history</code> as given: a vector for one series, else strata × time. Without an <code>Init</code> method the state starts at zero, and no <code>Init</code> pullback is needed.</p></li></ul><h2 id="extending-names" tabindex="-1">Names <a class="header-anchor" href="#extending-names" aria-label="Permalink to &quot;Names {#extending-names}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">What it does</th><th style="text-align:left;">Returns</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.ntrace"><code>ntrace(m, S)</code></a></td><td style="text-align:left;">how many rows a modifier&#39;s trace has</td><td style="text-align:left;"><code>Int</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.trace_rows"><code>trace_rows(m, S)</code></a></td><td style="text-align:left;">the names of a modifier&#39;s trace rows, so a call returns them by name</td><td style="text-align:left;">a named tuple of row counts, or <code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.blocks"><code>blocks(m)</code></a></td><td style="text-align:left;">a modifier&#39;s groups of strata</td><td style="text-align:left;">a tuple, or <code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.nstate"><code>nstate(m, S)</code></a></td><td style="text-align:left;">the number of state entries a modifier keeps for <code>S</code> strata</td><td style="text-align:left;"><code>Int</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.param_rows"><code>param_rows(m, S)</code></a></td><td style="text-align:left;">how many rows a whole-step modifier&#39;s parameters have, or <code>nothing</code> to skip the check</td><td style="text-align:left;">an <code>Int</code> or <code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.isstateless"><code>isstateless(m)</code></a></td><td style="text-align:left;">whether a modifier leaves its state unchanged, so it records no trace</td><td style="text-align:left;"><code>Bool</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.islinear"><code>islinear(x)</code></a></td><td style="text-align:left;">whether a coupling or whole-step modifier is a matrix, so a call runs that matrix in its place</td><td style="text-align:left;"><code>Bool</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.param"><code>param(x, k, t)</code></a></td><td style="text-align:left;">reads a parameter for stratum <code>k</code> at time <code>t</code></td><td style="text-align:left;">a value</td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.add_param!"><code>add_param!(x̄, x, v, k, t)</code></a></td><td style="text-align:left;">adds to a parameter&#39;s cotangent</td><td style="text-align:left;"><code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.cotangent"><code>cotangent(x̄, name)</code></a></td><td style="text-align:left;">the cotangent of a field</td><td style="text-align:left;">a cotangent, or <code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.add_cotangent!"><code>add_cotangent!(x̄, v, idx...)</code></a></td><td style="text-align:left;">adds to a cotangent</td><td style="text-align:left;"><code>nothing</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/public#ComposableRecurrences.PieceInterface"><code>PieceInterface</code></a></td><td style="text-align:left;">the conformance test for a new type, built on the Interfaces.jl package</td><td style="text-align:left;">a test result</td></tr></tbody></table><h2 id="overview-gradients" tabindex="-1">Checking your type <a class="header-anchor" href="#overview-gradients" aria-label="Permalink to &quot;Checking your type {#overview-gradients}&quot;">​</a></h2><p><code>PieceInterface</code> takes one <code>Arguments</code> per role the type has, each holding the type, the role and the arguments after the role:</p><ul><li><p><code>(s, history)</code> for <code>Init()</code>;</p></li><li><p><code>(v, s, t)</code>, with vectors, for a modifier&#39;s <code>Step()</code>;</p></li><li><p><code>(q, p, t)</code> for <code>Pressure()</code>;</p></li><li><p><code>(v, s, N)</code>, with a float <code>N</code>, for a depletion form;</p></li><li><p><code>(r, v, s, v′, s′, t)</code> for <code>Trace()</code>, with <code>r</code> as <a href="/previews/PR883/developer/extending-traces#extending-trace-own">Traces</a> gives. A blockwise group takes <code>g</code> after <code>t</code>, and its arguments are tuples of <code>Ref</code>s.</p></li></ul><p>It also checks that the rule finds any <code>pullback!</code> the type has. The optional checks are <code>:pointwise</code> and <code>:nstate</code> for a pointwise step and the state length, <code>:blocks</code> for a blockwise step and <code>:pullback</code>. The <code>:pullback</code> check compares each <code>pullback!</code> for <code>Step()</code> or <code>Pressure()</code> with the ForwardDiff Jacobian of <code>forward!</code> on the same inputs, so it needs <code>using ForwardDiff</code>.</p><p><a href="/previews/PR883/lib/public#ComposableRecurrences.NoAdjoint"><code>NoAdjoint(op)</code></a> is the same operator differentiated by automatic differentiation instead of its <a href="/previews/PR883/explanation/adjoints-and-backends#adjoints-backends">rule</a>, so its gradient checks the rule&#39;s and timing both compares their cost.</p><p>The names below are internal helpers. They help check a new type, but they may change without notice.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">What it does</th><th style="text-align:left;">Returns</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/previews/PR883/lib/internals#ComposableRecurrences.uses_adjoint"><code>ComposableRecurrences.uses_adjoint(m, role)</code></a></td><td style="text-align:left;">whether the rule calls <code>m</code>&#39;s <code>pullback!</code> for <code>role</code></td><td style="text-align:left;"><code>Bool</code></td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/internals#ComposableRecurrences.Run"><code>ComposableRecurrences.Run()</code></a></td><td style="text-align:left;">the role of an operator&#39;s whole call</td><td style="text-align:left;">a type with no fields</td></tr><tr><td style="text-align:left;"><a href="/previews/PR883/lib/internals#ComposableRecurrences.test_adjoint"><code>ComposableRecurrences.test_adjoint(backend, op, ComposableRecurrences.Run(), args...)</code></a></td><td style="text-align:left;">runs the rule tester of an automatic differentiation package on an operator&#39;s rule</td><td style="text-align:left;">a test result</td></tr></tbody></table><p>For an operator, pass <code>Run()</code> as the role to <code>uses_adjoint</code>, <code>PieceInterface</code> and <code>test_adjoint</code>. <code>test_adjoint</code> needs Mooncake, or Enzyme with EnzymeTestUtils, loaded.</p>',19)])])}const g=t(r,[["render",s]]);export{f as __pageData,g as default};
